import{_ as o,y as n,a as s,o as a,a2 as t,D as d}from"./chunks/framework.DCcmcJcL.js";const w=JSON.parse('{"title":"RMA","description":"","frontmatter":{},"headers":[],"relativePath":"configure/rma.md","filePath":"configure/rma.md","lastUpdated":1789441803000}'),l={name:"configure/rma.md"};function i(u,e,h,c,g,p){const r=n("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=t('<h1 id="rma" tabindex="-1">RMA <a class="header-anchor" href="#rma" aria-label="Permalink to &quot;RMA&quot;">​</a></h1><p>These settings control return requests (RMA, return merchandise authorization): how long customers have to request a return, the return policy they read, the files that can be attached, whether a closed return can be reopened, and which product types can be returned. How returns are requested and handled is described in <a href="./../orders/rma.html">Return Merchandise Authorization (RMA)</a>.</p><h2 id="set-up-returns" tabindex="-1">Set up returns <a class="header-anchor" href="#set-up-returns" aria-label="Permalink to &quot;Set up returns&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; RMA</strong>.</li><li>If your store has more than one channel or language, choose them at the top of the screen.</li><li>In <strong>RMA</strong>, set the options described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),d(r,{src:"/images/configure/rma-settings.png",alt:"RMA screen with the return window, return policy and allowed options"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Default allowed days</strong></td><td>The number of days after an order is placed within which the customer can request a return, for products without an active RMA rule of their own. The default is <code>7</code>.</td></tr><tr><td><strong>Return Policy</strong></td><td>The return policy customers read on the storefront before they submit a return request. The default is <code>7 days return policy.</code></td></tr><tr><td><strong>Allowed File Extension</strong></td><td>The file types customers and admins can attach to a return request, such as photos of the product: <strong>JPG / JPEG</strong>, <strong>PNG</strong> and <strong>WEBP</strong>. All three are allowed by default.</td></tr><tr><td><strong>Allow Reopening Cancelled Returns</strong></td><td><strong>Yes</strong>, the default, lets an admin, or the customer while the return window is still open, reopen a return that was cancelled. It moves back to <strong>Pending Review</strong>. <strong>No</strong> makes a cancelled return final.</td></tr><tr><td><strong>Allow Reopening Declined Returns</strong></td><td><strong>Yes</strong>, the default, lets an admin, or the customer while the return window is still open, reopen a return that was declined. It moves back to <strong>Pending Review</strong>. <strong>No</strong> makes a declined return final.</td></tr><tr><td><strong>Allow Product Type For RMA</strong></td><td>The product types that can be returned: <strong>Simple</strong>, <strong>Configurable</strong>, <strong>Bundle</strong> and <strong>Grouped</strong>. All four are selected by default.</td></tr></tbody></table><p>All settings are per channel, and <strong>Return Policy</strong> is also per language.</p><h2 id="which-products-can-be-returned" tabindex="-1">Which products can be returned <a class="header-anchor" href="#which-products-can-be-returned" aria-label="Permalink to &quot;Which products can be returned&quot;">​</a></h2><p>A product can be returned only when both of these are true:</p><ul><li>Its product type is selected in <strong>Allow Product Type For RMA</strong>.</li><li><strong>Allow RMA</strong> is switched on for the product on its edit page. It&#39;s off for new products, so switch it on for each product customers may return. See <a href="./../product-types/products.html#rma">Products</a> and <a href="./../orders/rma.html#allow-returns-on-a-product">Allow returns on a product</a>.</li></ul><p>Its return window is the return period of the active rule chosen in the product&#39;s <strong>RMA Rules</strong> field, or <strong>Default allowed days</strong> when it has none. RMA rules are managed under <strong>Sales &gt;&gt; RMA &gt;&gt; Rules</strong>.</p><h3 id="when-changes-take-effect" tabindex="-1">When changes take effect <a class="header-anchor" href="#when-changes-take-effect" aria-label="Permalink to &quot;When changes take effect&quot;">​</a></h3><p>The return window, and whether a product can be returned, are fixed when the order is placed. Changes to <strong>Default allowed days</strong>, <strong>Allow Product Type For RMA</strong>, a product&#39;s <strong>Allow RMA</strong> or <strong>RMA Rules</strong>, or the rules themselves apply only to orders placed afterwards. <strong>Return Policy</strong>, <strong>Allowed File Extension</strong> and the two reopening settings take effect straight away.</p>',8))])}const m=o(l,[["render",i]]);export{w as __pageData,m as default};
